import re
import json
import logging

import xmltodict
from funcy import join
from time import time, sleep
from datetime import timedelta
from contextlib import contextmanager
from taf.sbts.oam.coam.admin import admin
from taf.ul.energy_efficiency_monitoring.exceptions import NoCountersDataSaved, NoMeasurementPeriodSaved,\
    WrongNumberOfCounterValues


class EnergyEfficiencyMonitoring:

    MONITORING_PARAMS = {
        '{}/MNL-1/MNLENT-1/FEATCADM-1': ['actPowerMeter'],
        '{}/MNL-1/MNLENT-1/PMMNL-1': ['mtBtsEnergyMonitoring', 'mtSBTSRfmEnergyMonitoring', 'mtSBTSSmEnergyMonitoring']
    }
    DISABLED_MONITORING_PARAMS_VALUES = {
        'actPowerMeter': 'false',
        'mtBtsEnergyMonitoring': 'disabled',
        'mtSBTSRfmEnergyMonitoring': 'disabled',
        'mtSBTSSmEnergyMonitoring': 'disabled'
    }
    ENERGY_CONSUMPTION_COUNTERS = [
        'M40002C0',
        'M40002C1',
        'M40002C2'
    ]
    ALLOWED_INTERVALS = ['15min', '30min', '60min', '360min', '720min', '1440min']

    def __init__(self):
        self.coam_admin = admin()
        self._admin_credentials = None
        self._mrbts_distname = None
        self._monitoring_params = None
        self._measurement_interval = None
        self._target_monitoring_params_values = {
            'actPowerMeter': 'true',
            'mtBtsEnergyMonitoring': '15min',
            'mtSBTSRfmEnergyMonitoring': '15min',
            'mtSBTSSmEnergyMonitoring': '15min'
        }
        self._monitoring_period_for_features_status = {
            'disabled': {
                'start': None,
                'stop': None
            },
            'enabled': {
                'start': None,
                'stop': None
            }
        }
        self._monitoring_counters_values_for_features_status = {
            'disabled': None,
            'enabled': None
        }

    @property
    def monitoring_counters_values(self):
        if self._monitoring_counters_values_for_features_status['disabled'] is None:
            raise NoCountersDataSaved('Values for monitoring counters have not been saved correctly. Please call '
                                      'save_energy_consumption_counters_values with ee_features_status=disabled.')
        if self._monitoring_counters_values_for_features_status['enabled'] is None:
            raise NoCountersDataSaved('Values for monitoring counters have not been saved correctly. Please call '
                                      'save_energy_consumption_counters_values with ee_features_status=enabled.')
        return self._monitoring_counters_values_for_features_status

    @property
    def monitoring_periods(self):
        if self._monitoring_period_for_features_status['disabled']['start'] is None \
                or self._monitoring_period_for_features_status['disabled']['stop'] is None:
            raise NoMeasurementPeriodSaved('Undefined measurement period for disabled status. Please call '
                                           'start_measurement_period and stop_measurement_period '
                                           'with ee_features_status=disabled.')
        if self._monitoring_period_for_features_status['enabled']['start'] is None \
                or self._monitoring_period_for_features_status['enabled']['stop'] is None:
            raise NoMeasurementPeriodSaved('Undefined measurement period for enabled status. Please call '
                                           'start_measurement_period and stop_measurement_period '
                                           'with ee_features_status=enabled.')
        return self._monitoring_period_for_features_status

    @contextmanager
    def open_admin_connection(self):
        if self._admin_credentials is None:
            raise ValueError('Unable to open admin connection - connection has not been configured. '
                             'Please call configure_admin_connection.')
        alias = self._admin_credentials['name']
        try:
            connection = self.coam_admin.connect_to(**self._admin_credentials)
            yield connection
        finally:
            self.coam_admin.teardown(connection=alias)

    def configure_admin_connection(self, ip_address='192.168.255.129', username='Nemuadmin', password='nemuuser', alias=None, **kwargs):
        """
        Configure parameters for BTS connection.
        :param ip_address: IP of BTS; default 192.168.255.129
        :type  ip_address: str
        :param username:   name of BTS user; default Nemuadmin
        :type  username:   str
        :param password:   password to log in for BTS user; default nemuuser
        :type  password:   str
        :param alias:      alias for admin connection, if None the alias is generated inside the method; default None
        :type  alias:      Union[None, str]
        :param kwargs:     other named parameters supported by connect_to method from taf.sbts.oam.coam.admin library
        :return: None
        """
        self._admin_credentials = {
            'bts_host': ip_address,
            'username': username,
            'password': password,
            'name': alias if alias is not None else f'energy_efficiency_monitoring_{time()}'
        }
        self._admin_credentials.update(kwargs)
        logging.info(f'Configured admin connection details: {self._admin_credentials}')
        self._set_mrbts_distname()

    def get_counters_difference_for_enabled_disabled_features(self):
        """
        Count the difference between counters' values collected when EE feature was disabled and
        when EE feature was enabled. If more than one interval passed during measurement period the values are summed up
        keeping the same number of records for disabled and enabled measurement period.
        :return: dict in format:
        {
            'M40002C0': {
                'diff': {'kWh': -0.00046, 'raw': -46.0},
                'disabled': {'kWh': 0.08535, 'raw': 8535.0},
                'enabled': {'kWh': 0.08581, 'raw': 8581.0},
                'interval': '15min',
                'percentage gain': '-0.54%'
            },
            'M40002C1': {
                'diff': {'kWh': -0.0003, 'raw': -30.0},
                'disabled': {'kWh': 0.25901, 'raw': 25901.0},
                'enabled': {'kWh': 0.25931, 'raw': 25931.0},
                'interval': '15min',
                'percentage gain': '-0.12%'
            },
            'M40002C2': {
                'diff': {'kWh': -0.00076, 'raw': -76.0},
                'disabled': {'kWh': 0.34436, 'raw': 34436.0},
                'enabled': {'kWh': 0.34512, 'raw': 34512.0},
                'interval': '15min',
                'percentage gain': '-0.22%'
            }
        }
        """
        counters_records_disabled = self._get_records_of_counters_in_scope(ee_features_status='disabled')
        counters_records_enabled = self._get_records_of_counters_in_scope(ee_features_status='enabled')
        logging.debug(f'Counters in scope values - disabled feature: {counters_records_disabled}')
        logging.debug(f'Counters in scope values - enabled feature: {counters_records_enabled}')
        difference_for_counters = {}
        for counter_name, counter_values_disabled in counters_records_disabled.items():
            counter_values_enabled = counters_records_enabled[counter_name]
            values_nr_disabled = len(counter_values_disabled)
            values_nr_enabled = len(counter_values_enabled)
            if values_nr_disabled != values_nr_enabled:
                logging.debug(f'Counter {counter_name} values - disabled feature: {counter_values_disabled}')
                logging.debug(f'Counter {counter_name} values - enabled feature: {counter_values_enabled}')
                raise WrongNumberOfCounterValues(f'Counter {counter_name} has been collected during unequal '
                                                 f'number of PM periods for disabled and enabled status: '
                                                 f'{values_nr_disabled} != {values_nr_enabled}')
            record = {
                'disabled': {},
                'enabled': {},
                'diff': {},
                'percentage gain': None,
                'interval': self._measurement_interval
            }
            record['disabled']['raw'] = sum([counter_value['value'] for counter_value in counter_values_disabled])
            # the reported value is 100,000 times higher than the actual value (in kWh)
            record['disabled']['kWh'] = record['disabled']['raw'] / 100000.0

            record['enabled']['raw'] = sum([counter_value['value'] for counter_value in counter_values_enabled])
            # the reported value is 100,000 times higher than the actual value (in kWh)
            record['enabled']['kWh'] = record['enabled']['raw'] / 100000.0

            record['diff']['raw'] = record['disabled']['raw'] - record['enabled']['raw']
            # the reported value is 100,000 times higher than the actual value (in kWh)
            record['diff']['kWh'] = record['diff']['raw'] / 100000.0
            record['percentage gain'] = f"{round(record['diff']['raw'] / abs(record['disabled']['raw']) * 100, 2)}%"
            logging.info(f'Record for counter {counter_name}: {record}')
            difference_for_counters[counter_name] = record
        self.__log_result(difference_for_counters)
        return difference_for_counters

    def get_parameters_from_configuration(self, params_dict):
        """
        Get parameters' values from SCF
        :param params_dict: dictionary where key is a distName and value is a list of parameters names
        :return: {
            'dist_name1': {
                'param_name1': value1,
                'param_name2': value2,
                ...
            },
            ...
        }
        """
        with self.open_admin_connection() as connection:
            scf_file_content = self.coam_admin.get_scf(connection=connection, timeout=60)
            scf_file_content_dict = xmltodict.parse(scf_file_content)
            managed_objects = scf_file_content_dict['raml']['cmData']['managedObject']
            params_from_configuration = {}
            for dist_name, params_list in params_dict.items():
                for managed_object in managed_objects:
                    if managed_object['@distName'] == dist_name:
                        all_params = self._parse_mo_parameters(managed_object['p'])
                        params_from_configuration[dist_name] = {param: all_params[param] for param in all_params.keys()
                                                                if param in params_list}
            return params_from_configuration

    def get_energy_consumption_counters_values(self):
        """
        Get values of all BTS energy consumption counters
        :return: dict in format
        {
            'counter_name' : {
                'timestamp1' : value1,
                'timestamp2' : value2,
                ...
            }
        }
        """
        with self.open_admin_connection() as connection:
            all_counters_info = self.coam_admin.get_pm_counters(counter_ids=','.join(self.ENERGY_CONSUMPTION_COUNTERS),
                                                                connection=connection, timeout=60)
            energy_consumption_counters = all_counters_info["BTS"]
            if "BTS" in energy_consumption_counters.keys():
                energy_consumption_counters = energy_consumption_counters["BTS"]
            energy_consumption_counters = energy_consumption_counters[self._mrbts_distname]["SBTS_Energy_Consumption"]
            logging.info(f'Collected values of counters: {energy_consumption_counters.keys()}')
            return energy_consumption_counters

    def modify_default_monitoring_params_values(self, **kwargs):
        """
        Set monitoring parameters to values different from default.
        :param kwargs: one or more monitoring parameters with values.
        :return: None
        """
        for param_name, param_value in kwargs.items():
            self.__validate_interval_value(param_value)
            if param_name in self._target_monitoring_params_values.keys():
                self._target_monitoring_params_values[param_name] = param_value
                logging.info(f"Target value for parameter {param_name} has been set to {param_value}")
            else:
                raise ValueError(f"Given parameter name {param_name} does not match any monitoring parameter's name")

    def recommission_monitoring_params_with_target_values(self):
        """
        Set parameters defined in MONITORING_PARAMS in BTS configuration to target values enabling energy efficiency monitoring.
        :return: None
        """
        logging.info('Starting recommissioning of monitoring parameters...')
        self._recommission_monitoring_params(monitoring_params_values=self._target_monitoring_params_values)
        logging.info('All monitoring parameters has been set to target values')

    def recommission_monitoring_params_with_disabled_values(self):
        """
        Set parameters defined in DISABLED_MONITORING_PARAMS_VALUES in BTS configuration to disable energy efficiency monitoring.
        :return: None
        """
        logging.info('Starting recommissioning of monitoring parameters...')
        self._recommission_monitoring_params(monitoring_params_values=self.DISABLED_MONITORING_PARAMS_VALUES)
        logging.info('All monitoring parameters has been set to target values')

    def save_energy_consumption_counters_values(self, ee_features_status, filepath=None):
        """
        Save current values of energy consumption counters for given EE features status.
        Additionally log them to JSON file.
        :param ee_features_status: disabled or enabled
        :type  ee_features_status: str
        :param filepath:           full path to JSON file where the counters are saved
        :type  filepath:           str
        :return: None
        """
        if ee_features_status not in self._monitoring_counters_values_for_features_status.keys():
            raise ValueError('Wrong EE Features status. Should be enabled or disabled.')
        counters_values = self.get_energy_consumption_counters_values()
        self._monitoring_counters_values_for_features_status[ee_features_status] = counters_values
        logging.debug(f"Energy consumption counters' values has been saved "
                      f"for {ee_features_status} EE features: {counters_values}")
        if filepath:
            with open(filepath, 'w') as counters_file:
                json.dump(counters_values, counters_file)
                logging.info(f'Counters saved to file: {filepath}')

    def start_measurement_period(self, ee_features_status, interval):
        """
        Save start time of period during which are collected counters that will be included in counting difference
        in power consumption between enabled and disabled features.
        :param ee_features_status: disabled or enabled
        :type  ee_features_status: str
        :param interval:           time interval set for counters collection
        :type  interval:           str
        :return: None
        """
        if ee_features_status not in self._monitoring_period_for_features_status.keys():
            raise ValueError('Wrong EE Features status. Should be enabled or disabled.')
        self.__validate_interval_value(value=interval)
        self._measurement_interval = interval
        current_pm_period = self._get_current_pm_period(interval)
        self._monitoring_period_for_features_status[ee_features_status]['start'] = int(current_pm_period[0])
        logging.info(self._monitoring_period_for_features_status)

    def stop_measurement_period(self, ee_features_status):
        """
        Save stop time of period during which are collected counters that will be included in counting difference
        in power consumption between enabled and disabled features.
        :param ee_features_status: disabled or enabled
        :type  ee_features_status: str
        :return: None
        """
        if ee_features_status not in self._monitoring_period_for_features_status.keys():
            raise ValueError('Wrong EE Features status. Should be enabled or disabled.')
        self._monitoring_period_for_features_status[ee_features_status]['stop'] = int(time())
        logging.info(self._monitoring_period_for_features_status)

    def verify_all_monitoring_params_are_set_correctly(self):
        """
        Verify if all monitoring parameters are set to target values.
        :return: None
        """
        monitoring_params_values = self.get_parameters_from_configuration(self._monitoring_params)
        monitoring_params_values = join(monitoring_params_values.values())
        all_params_set_correctly = True
        for param_name, param_value in self._target_monitoring_params_values.items():
            if param_name in monitoring_params_values.keys():
                if monitoring_params_values[param_name] == param_value:
                    logging.info(f'Parameter {param_name} has correct value: {param_value}')
                else:
                    all_params_set_correctly = False
                    logging.warning(f'Parameter {param_name} has incorrect value: {monitoring_params_values[param_name]}')
            else:
                all_params_set_correctly = False
                logging.warning(f'Parameter {param_name} is not configured!')
        return all_params_set_correctly

    def wait_for_next_pm_period(self, interval="15min", delay=30):
        """
        Wait for the next counter cycle, indicated by the interval
        :param interval:                    Interval of the counter in minutes, e.g. "15min"
        :type  interval:                    str
        :param delay:                       Number of seconds to wait after the new period starts
        :type  delay:                       int
        :return: pm_period_start_time, pm_period_end_time
        """
        interval_minute_value = re.match(r'(?P<MINUTES>\d+)min', interval).group('MINUTES')
        interval_seconds_value = int(interval_minute_value) * 60
        waiting_time = interval_seconds_value - int(time()) % interval_seconds_value + delay
        logging.info(f'waiting_time={waiting_time}')
        logging.debug('Waiting for new PM period : {}'.format(timedelta(seconds=waiting_time)))
        sleep(waiting_time)

        current_timestamp = int(time())
        pm_period_start_time = current_timestamp - current_timestamp % 60
        pm_period_end_time = pm_period_start_time + interval_seconds_value

        return pm_period_start_time, pm_period_end_time

    def _get_current_pm_period(self, interval):
        interval_minute_value = re.match(r'(?P<MINUTES>\d+)min', interval).group('MINUTES')
        logging.info(f'interval_minute_value={interval_minute_value}')
        interval_seconds_value = int(interval_minute_value) * 60
        logging.info(f'interval_seconds_value={interval_seconds_value}')
        current_time = int(time())
        time_to_period_start = current_time % interval_seconds_value
        time_to_period_end = interval_seconds_value - time_to_period_start
        period_start = current_time - time_to_period_start
        period_end = current_time + time_to_period_end
        return period_start, period_end

    def _get_records_of_counters_in_scope(self, ee_features_status):
        collected_counters = self.monitoring_counters_values[ee_features_status]
        logging.debug(f'Collected counters for {ee_features_status}: {collected_counters}')
        start_time = self.monitoring_periods[ee_features_status]['start']
        stop_time = self.monitoring_periods[ee_features_status]['stop']
        if stop_time <= start_time:
            raise ValueError(f'Wrong measurement period: stop time "{stop_time}" <= start time "{start_time}"')
        counters_in_scope = {counter_name: [] for counter_name in collected_counters.keys()}
        for counter_name, counter_values in collected_counters.items():
            timestamps = self._get_timestamps_in_scope(counter_values, start_time=start_time, stop_time=stop_time)
            for timestamp in timestamps:
                counters_in_scope[counter_name].append({
                    'timestamp': timestamp,
                    'value': float(counter_values[timestamp])
                })
            logging.info(f'Counters in scope for {counter_name}: {counters_in_scope[counter_name]}')
        return counters_in_scope

    def _get_timestamps_in_scope(self, counter_values, start_time, stop_time):
        timestamps = counter_values.keys()
        start_time = int(start_time)
        stop_time = int(stop_time)
        timestamps_in_scope = [timestamp for timestamp in timestamps if start_time <= int(timestamp) < stop_time]
        timestamps_in_scope = set(timestamps_in_scope)
        if not timestamps_in_scope:
            raise ValueError(f'No counters with timestamps between start_time="{start_time}" and '
                             f'stop_time="{stop_time}"')
        logging.info(f'Timestamps in scope <{start_time}, {stop_time}): {timestamps_in_scope}')
        return timestamps_in_scope

    def _parse_mo_parameters(self, raw_params):
        parsed_params = {}
        for param in raw_params:
            parsed_params[param['@name']] = param['#text']
        return parsed_params

    def _recommission_monitoring_params(self, monitoring_params_values):
        with self.open_admin_connection() as connection:
            for dist_name, params_list in self._monitoring_params.items():
                for param_name in params_list:
                    param_value = monitoring_params_values[param_name]
                    self.coam_admin.perform_parameter_recommissioning(dist_name=dist_name, parameter=param_name,
                                                                      operation='update', value=param_value,
                                                                      connection=connection)
                    logging.info(f'Parameter {param_name} has been set to {param_value}')

    def _set_mrbts_distname(self):
        with self.open_admin_connection() as connection:
            bts_info = self.coam_admin.get_bts_info(connection=connection, timeout=60)
            self._mrbts_distname = bts_info['id']['configuration']
            logging.debug(f'Set MRBTS distName: {self._mrbts_distname}')
            self._monitoring_params = {}
            for dist_name, params in self.MONITORING_PARAMS.items():
                dist_name_with_mrbts_id = dist_name.format(self._mrbts_distname)
                self._monitoring_params[dist_name_with_mrbts_id] = params
            logging.debug(f'Filled in the MRBTS distName for monitoring params: {self._monitoring_params}')

    def __log_result(self, result_dict):
        msg_to_log = f"{'-' * 27}RESULT{'-' * 27}\n"
        for counter_name, result in result_dict.items():
            msg_to_log += f"{counter_name}:\n" \
                          f"\tvalue for disabled EE features:    {result['disabled']['raw']}\n" \
                          f"\t                                   {result['disabled']['kWh']} kWh\n" \
                          f"\tvalue for enabled EE features:     {result['enabled']['raw']}\n" \
                          f"\t                                   {result['enabled']['kWh']} kWh\n" \
                          f"\tdifference:                        {result['diff']['raw']}\n" \
                          f"\t                                   {result['diff']['kWh']} kWh\n" \
                          f"\tpercentage gain:                   {result['percentage gain']}\n" \
                          f"\ttime interval defined by user:     {result['interval']}\n" \
                          f"{'-' * 60}\n"
        logging.info(msg_to_log)

    def __validate_interval_value(self, value):
        if value not in self.ALLOWED_INTERVALS:
            raise ValueError(f"Interval's value={value} is not among allowed interval values: {self.ALLOWED_INTERVALS}")
